  "update.ownChoice": "Eigið val",
  "update.useDefault": "Fylgja sjálfgefnu",
  "update.afterBackupOrphans":
    "Docker heldur myndinni sem gámurinn keyrði á áður, nú án merkis, og Unraid skráir hana sem föðurlausa mynd. Það eru eðlilegar eftirstöðvar heppnaðrar uppfærslu, ekki merki um mistök, og einmitt það sem þarf til að fara hratt til baka í fyrri mynd. Ef þú vilt ekki halda henni eyðir rofinn „Fjarlægja gömlu ímyndina eftir uppfærslu“ undir Stillingar, Tímaáætlun, Uppfærslur eftir afritun myndinni sem var leyst af hólmi rétt eftir uppfærsluna.",
