  "breakdown.hint": "Hvað tekur pláss í nýjasta afritinu, stærst fyrst, og hve mikið af því síðasta afritun kom með nýtt eða breytt. Breytt skrá telst með allri sinni stærð, því restic segir ekki hve mikið af henni breyttist. Stærðirnar eru skráastærðir fyrir afritunarhreinsun og þjöppun. BombVault les þær úr vísi geymslunnar án þess að lesa skrárnar og heldur þeim uppfærðum eftir hverja afritun.",
