  "settings.pathMode.local": "Staðbundið",
  "settings.compression": "Þjöppun",
  "settings.compressionInfo": "Hvernig restic pakkar nýjum gögnum í þessa geymslu. Sjálfvirkt er sjálfgildi restic og hentar flestum gögnum. Hámark sparar meira pláss og kostar meiri örgjörvatíma við afritun og afritsflutning. Slökkt geymir gögnin óþjöppuð, sem hjálpar þegar þau eru þegar þjöppuð, eins og myndbönd eða ljósmyndir. Geymsla á gamla sniðinu útgáfu 1 getur ekki þjappað og hunsar þessa stillingu.",
