  "flash.zipExport.keepHistoryHint": "Slökkt: geymir eina flash-latest.zip sem er skrifað yfir í hvert sinn. Kveikt: geymir N nýjustu tímastimplaðar flash-<dagsetning>.zip skrár. Þetta er óháð restic-varðveislu: slökkt geymir eina, alltaf yfirskrifaða skrá (fyllir aldrei áfangastaðinn); kveikt geymir N nýjustu og eyðir eldri.",
