  "mcp.stepOAuth": "Kveiktu á innskráningu",
  "mcp.setupChatGPT": "Opnaðu Stillingar, Forrit og tenglar í ChatGPT og kveiktu á forritaraham undir Ítarlegar stillingar. Veldu síðan Búa til, gefðu tenglinum nafn, límdu slóð tengilsins inn sem slóð MCP-þjóns, veldu OAuth sem auðkenningu, staðfestu að þú treystir honum og búðu hann til.",
  "mcp.setupClaudeAi": "Opnaðu Stillingar, Tenglar á claude.ai og veldu Bæta við sérsniðnum tengli. Gefðu honum nafn, límdu slóð tengilsins inn, láttu OAuth-auðkenni biðlara og leyndarmál vera tóm og bættu honum við. Veldu síðan Tengjast.",
  "mcp.copyConnector": "Afrita slóð tengils",
  "mcp.oauthProxyNote": "Þjónustan kallar á /mcp, /oauth/ og /.well-known/ frá eigin þjónum, svo öfugur milliþjónn með eigin innskráningu þarf að hleypa þessum slóðum í gegn til BombVault.",
