  "mcp.notePerplexity": "Enn sem komið er tengist aðeins Mac-forrit Perplexity við MCP-netþjóna á tölvunni þinni eða netinu; Windows-forritið og vefsíðan gera það ekki.",
  "mcp.noteGrok": "Skjölun Grok sýnir ekki tengiformið í smáatriðum. Ef það býður aðeins upp á innskráningu og engan reit fyrir haus getur það ekki enn notað BombVault-lykil.",
  "mcp.certNotForThisAddress": "Skilríki BombVault nefnir ekki {host}, svo aðstoðarmenn neita að tengjast þessu vistfangi. Bættu vistfanginu við skilríkið og sæktu það svo fyrir brotin.",
