  "anomaly.settings.title": "Frávik",
  "anomaly.settings.hint": "Ber hvert afrit færslu saman við hennar eigin sögu og tilkynnir það sem passar ekki. Keyrir í bakgrunni eftir hvert afrit og hægir ekki á neinu. Flestar athuganir hefjast eftir 10 afrit af færslu; bilanir, endurskrift mestra gagna og nær tóm uppspretta eru athuguð frá upphafi. Laust pláss er vaktað fyrir staðbundnar geymslur og rclone geymslur sem gefa það upp; á notendadeilingu Unraid er það laust pláss alls fylkisins.",
