  "anomaly.settings.sensitivity": "Næmi",
  "anomaly.settings.sensitivityHint": "Strangt tilkynnir minni breytingar, Rúmt aðeins stórar, Jafnvægi hentar flestum netþjónum. Hver færsla getur haft sína eigin stillingu undir Frávik, Vöktun.",
  "anomaly.settings.notifyMin": "Senda tilkynningu fyrir",
  "anomaly.settings.notifyHint": "Notar rásirnar sem eru stilltar undir Tilkynningar. Hver færsla getur breytt þessu undir Frávik, Vöktun. Endurteknar bilanir í afritum og gagnagrunnsafritum og misheppnaðar áætlaðar endurheimtarathuganir senda nú þegar eigin skilaboð og eru því ekki sendar í annað sinn.",
  "anomaly.settings.notifyMuted": "Ekkert er sent eins og er: tilkynningar eru slökktar eða engin rás er stillt.",
  "anomaly.settings.openNotifications": "Opna stillingar tilkynninga",
  "anomaly.settings.holdToggle": "Geyma gömul afrit þegar uppspretta minnkar mikið eða er endurskrifuð",
  "anomaly.settings.holdHint": "Þrjár niðurstöður stöðva eyðingu gamalla afrita: uppspretta sem er skyndilega nær tóm, uppspretta sem hefur minnkað mikið og afrit sem vistaði meirihluta gagnanna aftur, eins og gíslatökuforrit lítur út. Annars myndi varðveislan eyða góðu eldri afritunum einu í einu. Á meðan slíkt frávik er opið eru gömul afrit einungis þeirrar færslu (eða þess gagnagrunnsafrits eða ZFS gagnasafns) geymd; allt annað er hreinsað eins og venjulega. Kvittaðu fyrir frávikið eða merktu það sem væntanlegt til að halda áfram.",
